import sys, docx
from docx.oxml.ns import qn
path = sys.argv[1]
d = docx.Document(path)
cp = d.core_properties
print("FILE:", path)
print("Core:", dict(author=cp.author, last_modified_by=cp.last_modified_by, created=cp.created, modified=cp.modified, title=cp.title, subject=cp.subject, comments=cp.comments, keywords=cp.keywords, category=cp.category, revision=cp.revision))
# iterate body in order
body = d.element.body
def para_text(p):
    texts = []
    for node in p.iter():
        if node.tag == qn('w:t'):
            texts.append(node.text or '')
        elif node.tag == qn('w:delText'):
            texts.append('[DEL:' + (node.text or '') + ']')
        elif node.tag == qn('w:tab'):
            texts.append('\t')
        elif node.tag == qn('w:br'):
            texts.append('\n')
    return ''.join(texts)
for child in body.iterchildren():
    if child.tag == qn('w:p'):
        style = child.find(qn('w:pPr'))
        sname = ''
        if style is not None and style.find(qn('w:pStyle')) is not None:
            sname = style.find(qn('w:pStyle')).get(qn('w:val'))
        t = para_text(child)
        flags = []
        if child.findall('.//' + qn('w:ins')): flags.append('INS')
        if child.findall('.//' + qn('w:del')): flags.append('DEL')
        if child.findall('.//' + qn('w:vanish')): flags.append('HIDDEN')
        if child.findall('.//' + qn('w:strike')): flags.append('STRIKE')
        if child.findall('.//' + qn('w:commentReference')): flags.append('COMMENTREF')
        if t.strip() or flags:
            print(f"[P:{sname}]{'['+','.join(flags)+']' if flags else ''} {t}")
    elif child.tag == qn('w:tbl'):
        print("[TABLE]")
        for r in child.iter(qn('w:tr')):
            cells = []
            for c in r.iter(qn('w:tc')):
                ct = ' / '.join(para_text(p) for p in c.iter(qn('w:p')))
                cells.append(ct)
            print("  | " + " | ".join(cells))
        print("[/TABLE]")
    elif child.tag == qn('w:sectPr'):
        pass
# headers/footers
for i, s in enumerate(d.sections):
    for kind in ['header', 'footer', 'first_page_header', 'first_page_footer', 'even_page_header', 'even_page_footer']:
        try:
            h = getattr(s, kind)
            if h is not None and not h.is_linked_to_previous:
                t = '\n'.join(p.text for p in h.paragraphs if p.text.strip())
                for tb in h.tables:
                    for row in tb.rows:
                        t += '\n  | ' + ' | '.join(c.text for c in row.cells)
                if t.strip(): print(f"[{kind.upper()} s{i}] {t}")
        except Exception as e:
            pass
# comments
import zipfile, re
z = zipfile.ZipFile(path)
for n in z.namelist():
    if 'comments' in n or 'footnotes' in n or 'endnotes' in n:
        x = z.read(n).decode('utf8', 'ignore')
        txt = re.sub(r'<[^>]+>', ' ', x)
        txt = re.sub(r'\s+', ' ', txt)
        print(f"[{n}] {txt[:3000]}")
print("PARTS:", z.namelist())
EOF
