import os, subprocess, zipfile, re, openpyxl, email
from email import policy
out = "/tmp/txt"
for root, dirs, files in os.walk("."):
    for f in files:
        p = os.path.join(root, f)
        dst = os.path.join(out, p[2:].replace('/', '__') + ".txt")
        try:
            if f.endswith(".pdf"):
                t = subprocess.run(["pdftotext", "-layout", p, "-"], capture_output=True, text=True).stdout
            elif f.endswith(".docx"):
                t = subprocess.run(["python3", "/tmp/dumpdocx.py", p], capture_output=True, text=True).stdout
            elif f.endswith(".xlsx"):
                wb = openpyxl.load_workbook(p, data_only=False)
                lines = []
                for ws in wb.worksheets:
                    lines.append(f"=== SHEET {ws.title} ({ws.sheet_state}) ===")
                    for row in ws.iter_rows():
                        vals = []
                        for c in row:
                            if c.value is not None:
                                s = f"{c.coordinate}={c.value}"
                                if c.comment: s += f" [COMMENT:{c.comment.text}]"
                                vals.append(s)
                        if vals: lines.append(" | ".join(vals))
                t = "\n".join(lines)
            elif f.endswith(".eml"):
                with open(p, 'rb') as fh:
                    msg = email.message_from_binary_file(fh, policy=policy.default)
                hdr = "\n".join(f"{k}: {v}" for k, v in msg.items())
                parts = []
                for part in msg.walk():
                    ct = part.get_content_type()
                    if ct.startswith("text/"):
                        parts.append(f"--- {ct} ---\n" + part.get_content())
                    elif part.get_filename():
                        parts.append(f"--- ATTACHMENT {part.get_filename()} ({ct}) ---")
                t = hdr + "\n\n" + "\n".join(parts)
            else:
                t = open(p, errors='ignore').read()
        except Exception as e:
            t = f"ERROR {e}"
        open(dst, "w").write(t)
print("done")
